    fn editor_slot_values(path: &std::path::Path, display_key: &str) -> Vec<String> {
        let entries = read_all_tags(path).expect("read carrier through metadata editor");
        entries
            .iter()
            .find(|entry| entry.display_key == display_key)
            .and_then(|entry| entry.per_file_values.first())
            .map(MetadataFieldValues::to_texts)
            .unwrap_or_default()
    }

    fn assert_saved_without_warnings(result: &crate::tui::app::MetadataEditorWriteResult) {
        assert!(
            matches!(&result.outcome, crate::tui::app::MetadataEditorWriteOutcome::Saved),
            "unexpected metadata write result: {result:?}"
        );
    }

    fn owned_test_values(values: &[&str]) -> Vec<String> {
        values.iter().map(|value| (*value).to_string()).collect()
    }

    fn saved_warnings(
        result: &crate::tui::app::MetadataEditorWriteResult,
    ) -> &[String] {
        match &result.outcome {
            crate::tui::app::MetadataEditorWriteOutcome::SavedWithWarnings { warnings } => warnings,
            other => panic!("expected saved-with-warnings outcome, got {other:?}"),
        }
    }

    fn assert_id3_multivalue_interop_warning(
        result: &crate::tui::app::MetadataEditorWriteResult,
        display_key: &str,
    ) {
        let warnings = saved_warnings(result);
        assert!(warnings.iter().any(|warning| {
            warning.contains(display_key)
                && warning.contains("ID3v2.4")
                && warning.contains("ffmpeg")
                && warning.contains("VLC")
                && warning.contains("preserve all values")
        }), "missing ID3 interoperability warning for {display_key}: {warnings:?}");
    }

    fn write_result_warnings(
        result: &crate::tui::app::MetadataEditorWriteResult,
    ) -> &[String] {
        match &result.outcome {
            crate::tui::app::MetadataEditorWriteOutcome::Saved => &[],
            crate::tui::app::MetadataEditorWriteOutcome::SavedWithWarnings { warnings } => warnings,
            other => panic!("expected successful metadata write, got {other:?}"),
        }
    }

    fn assert_mp4_multivalue_interop_warning(
        result: &crate::tui::app::MetadataEditorWriteResult,
        display_key: &str,
    ) {
        let warnings = write_result_warnings(result);
        assert!(warnings.iter().any(|warning| {
            warning.contains(display_key)
                && warning.contains("MP4 ilst")
                && warning.contains("multiple data atoms")
                && warning.contains("ffmpeg")
                && warning.contains("VLC")
                && warning.contains("preserve all values")
        }), "missing MP4 interoperability warning for {display_key}: {warnings:?}");
        assert!(
            !warnings.iter().any(|warning| {
                warning.contains(display_key)
                    && warning.contains("legacy joined representation")
            }),
            "native MP4 multi-value persistence must not report a legacy-join downgrade for {display_key}: {warnings:?}",
        );
    }

    fn mp4_text_atom_groups(
        path: &std::path::Path,
        ident: &lofty::mp4::AtomIdent<'_>,
    ) -> Vec<Vec<String>> {
        use lofty::file::AudioFile;

        let mut file = std::fs::File::open(path).expect("open MP4 fixture for physical assertion");
        let mp4 = lofty::mp4::Mp4File::read_from(
            &mut file,
            lofty::config::ParseOptions::new().read_properties(false),
        )
        .expect("parse MP4 fixture for physical assertion");
        let Some(ilst) = mp4.ilst() else {
            return Vec::new();
        };
        ilst.into_iter()
            .filter(|atom| atom.ident() == ident)
            .map(|atom| {
                atom.data()
                    .filter_map(|data| match data {
                        lofty::mp4::AtomData::UTF8(value)
                        | lofty::mp4::AtomData::UTF16(value) => Some(value.clone()),
                        _ => None,
                    })
                    .collect::<Vec<_>>()
            })
            .collect()
    }

    fn seed_mp4_native_multi_data_atom(
        path: &std::path::Path,
        ident: lofty::mp4::AtomIdent<'static>,
        values: &[&str],
    ) {
        use lofty::config::WriteOptions;
        use lofty::file::AudioFile;

        assert!(!values.is_empty());
        let mut file = std::fs::File::open(path).expect("open MP4 fixture for native seed");
        let mut mp4 = lofty::mp4::Mp4File::read_from(
            &mut file,
            lofty::config::ParseOptions::new().read_properties(false),
        )
        .expect("parse MP4 fixture for native seed");
        drop(file);
        if mp4.ilst().is_none() {
            mp4.set_ilst(lofty::mp4::Ilst::new());
        }
        let data = values
            .iter()
            .map(|value| lofty::mp4::AtomData::UTF8((*value).to_string()))
            .collect::<Vec<_>>();
        let atom = lofty::mp4::Atom::from_collection(ident.clone(), data)
            .expect("non-empty MP4 native seed atom");
        let ilst = mp4.ilst_mut().expect("seeded MP4 ilst");
        let _ = ilst.remove(&ident).count();
        ilst.insert(atom);
        mp4.save_to_path(path, WriteOptions::default())
            .expect("save native MP4 multi-data seed");
    }

    fn seed_mp4_separate_same_fourcc_atoms(
        path: &std::path::Path,
        item_key: lofty::tag::ItemKey,
        values: &[&str],
    ) {
        use lofty::config::WriteOptions;
        use lofty::file::{AudioFile, TaggedFileExt};
        use lofty::tag::{ItemValue, Tag, TagItem, TagType};

        let mut tagged = lofty::read_from_path(path).expect("read MP4 fixture for generic seed");
        if tagged.tag(TagType::Mp4Ilst).is_none() {
            tagged.insert_tag(Tag::new(TagType::Mp4Ilst));
        }
        let tag = tagged.tag_mut(TagType::Mp4Ilst).expect("seeded generic MP4 tag");
        tag.remove_key(&item_key);
        for value in values {
            assert!(tag.push(TagItem::new(
                item_key.clone(),
                ItemValue::Text((*value).to_string()),
            )));
        }
        tagged.save_to_path(path, WriteOptions::default())
            .expect("save separate-same-fourcc MP4 seed");
    }

    fn embedded_id3v2_bytes(path: &std::path::Path) -> Vec<u8> {
        let bytes = std::fs::read(path).expect("read carrier for physical ID3 assertion");
        if bytes.starts_with(b"ID3") {
            return bytes;
        }

        let (mut offset, big_endian) = if bytes.starts_with(b"RIFF")
            && bytes.get(8..12) == Some(&b"WAVE"[..])
        {
            (12usize, false)
        } else if bytes.starts_with(b"FORM")
            && bytes.get(8..12) == Some(&b"AIFF"[..])
        {
            (12usize, true)
        } else {
            panic!("unsupported physical ID3 carrier for {}", path.display());
        };

        while offset.checked_add(8).is_some_and(|end| end <= bytes.len()) {
            let chunk_id = &bytes[offset..offset + 4];
            let size_bytes: [u8; 4] = bytes[offset + 4..offset + 8]
                .try_into()
                .expect("four-byte RIFF/AIFF chunk size");
            let chunk_len = if big_endian {
                u32::from_be_bytes(size_bytes)
            } else {
                u32::from_le_bytes(size_bytes)
            } as usize;
            let payload_start = offset + 8;
            let payload_end = payload_start
                .checked_add(chunk_len)
                .unwrap_or_else(|| panic!("chunk length overflow in {}", path.display()));
            assert!(
                payload_end <= bytes.len(),
                "truncated RIFF/AIFF chunk in {}",
                path.display(),
            );
            if chunk_id.eq_ignore_ascii_case(b"ID3 ") {
                let payload = bytes[payload_start..payload_end].to_vec();
                assert!(
                    payload.starts_with(b"ID3"),
                    "ID3 chunk in {} lacks an ID3 header",
                    path.display(),
                );
                return payload;
            }
            offset = payload_end
                .checked_add(chunk_len & 1)
                .unwrap_or_else(|| panic!("chunk padding overflow in {}", path.display()));
        }
        panic!("missing ID3 chunk in {}", path.display());
    }

    fn id3_physical_text_values(path: &std::path::Path, frame_id: &str) -> Vec<String> {
        let bytes = embedded_id3v2_bytes(path);
        let mut cursor = std::io::Cursor::new(bytes);
        let tag = id3::Tag::read_from2(&mut cursor).expect("parse embedded ID3v2 payload");
        let matching = tag
            .frames()
            .filter(|frame| frame.id() == frame_id)
            .collect::<Vec<_>>();
        assert_eq!(
            matching.len(),
            1,
            "{frame_id} must persist as exactly one physical ID3 text frame",
        );
        matching[0]
            .content()
            .text_values()
            .expect("ID3 frame is textual")
            .map(str::to_string)
            .collect()
    }

    fn id3_physical_extended_text_value(
        path: &std::path::Path,
        description: &str,
    ) -> String {
        let bytes = embedded_id3v2_bytes(path);
        let mut cursor = std::io::Cursor::new(bytes);
        let tag = id3::Tag::read_from2(&mut cursor).expect("parse embedded ID3v2 payload");
        let matching = tag
            .extended_texts()
            .filter(|frame| frame.description.eq_ignore_ascii_case(description))
            .collect::<Vec<_>>();
        assert_eq!(
            matching.len(),
            1,
            "{description} must persist as exactly one physical ID3 TXXX frame",
        );
        matching[0].value.clone()
    }

    fn write_minimal_pcm_wav(path: &std::path::Path) {
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"RIFF");
        bytes.extend_from_slice(&38u32.to_le_bytes());
        bytes.extend_from_slice(b"WAVE");
        bytes.extend_from_slice(b"fmt ");
        bytes.extend_from_slice(&16u32.to_le_bytes());
        bytes.extend_from_slice(&1u16.to_le_bytes());
        bytes.extend_from_slice(&1u16.to_le_bytes());
        bytes.extend_from_slice(&44_100u32.to_le_bytes());
        bytes.extend_from_slice(&88_200u32.to_le_bytes());
        bytes.extend_from_slice(&2u16.to_le_bytes());
        bytes.extend_from_slice(&16u16.to_le_bytes());
        bytes.extend_from_slice(b"data");
        bytes.extend_from_slice(&2u32.to_le_bytes());
        bytes.extend_from_slice(&0i16.to_le_bytes());
        std::fs::write(path, bytes).expect("write minimal PCM WAV fixture");
    }

    fn write_minimal_pcm_aiff(path: &std::path::Path) {
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"FORM");
        bytes.extend_from_slice(&48u32.to_be_bytes());
        bytes.extend_from_slice(b"AIFF");
        bytes.extend_from_slice(b"COMM");
        bytes.extend_from_slice(&18u32.to_be_bytes());
        bytes.extend_from_slice(&1u16.to_be_bytes());
        bytes.extend_from_slice(&1u32.to_be_bytes());
        bytes.extend_from_slice(&16u16.to_be_bytes());
        // 44100.0 as an IEEE 754 80-bit extended precision value.
        bytes.extend_from_slice(&[0x40, 0x0e, 0xac, 0x44, 0, 0, 0, 0, 0, 0]);
        bytes.extend_from_slice(b"SSND");
        bytes.extend_from_slice(&10u32.to_be_bytes());
        bytes.extend_from_slice(&0u32.to_be_bytes());
        bytes.extend_from_slice(&0u32.to_be_bytes());
        bytes.extend_from_slice(&0i16.to_be_bytes());
        std::fs::write(path, bytes).expect("write minimal PCM AIFF fixture");
    }

    fn seed_id3v24_carrier(path: &std::path::Path) {
        use lofty::config::WriteOptions;
        use lofty::file::{AudioFile, TaggedFileExt};
        use lofty::tag::{ItemKey, ItemValue, Tag, TagItem, TagType};

        let mut tagged = lofty::read_from_path(path).expect("read carrier before ID3 seed");
        let mut tag = Tag::new(TagType::Id3v2);
        tag.insert_unchecked(TagItem::new(
            ItemKey::TrackTitle,
            ItemValue::Text("ID3 seed".to_string()),
        ));
        tagged.insert_tag(tag);
        tagged
            .save_to_path(path, WriteOptions::default())
            .expect("seed ID3v2.4 carrier through Lofty");
    }

    fn seed_lofty_text_tag(
        path: &std::path::Path,
        tag_type: lofty::tag::TagType,
        item_key: lofty::tag::ItemKey,
        value: &str,
    ) {
        use lofty::config::WriteOptions;
        use lofty::file::{AudioFile, TaggedFileExt};
        use lofty::tag::{ItemValue, Tag, TagItem};

        let mut tagged = lofty::read_from_path(path).expect("read carrier before tag seed");
        if tagged.tag(tag_type).is_none() {
            tagged.insert_tag(Tag::new(tag_type));
        }
        let tag = tagged.tag_mut(tag_type).expect("seeded tag container is present");
        tag.insert_unchecked(TagItem::new(
            item_key,
            ItemValue::Text(value.to_string()),
        ));
        tagged
            .save_to_path(path, WriteOptions::default())
            .expect("seed tag carrier through Lofty");
    }

    fn editor_values_in_lofty_tag(
        path: &std::path::Path,
        tag_type: lofty::tag::TagType,
        display_key: &str,
    ) -> Vec<String> {
        use lofty::file::TaggedFileExt;

        let tagged = lofty::read_from_path(path).expect("read tagged file for container assertion");
        let tag = tagged.tag(tag_type).expect("expected tag container");
        canonical_editor_fields_from_tag(tag)
            .into_iter()
            .find(|field| field.display_key == display_key)
            .map(|field| field.values.to_texts())
            .unwrap_or_default()
    }

    fn editor_values_in_optional_lofty_tag(
        path: &std::path::Path,
        tag_type: lofty::tag::TagType,
        display_key: &str,
    ) -> Vec<String> {
        use lofty::file::TaggedFileExt;

        let tagged = lofty::read_from_path(path).expect("read tagged file for optional container assertion");
        tagged
            .tag(tag_type)
            .map(canonical_editor_fields_from_tag)
            .and_then(|fields| {
                fields
                    .into_iter()
                    .find(|field| field.display_key == display_key)
            })
            .map(|field| field.values.to_texts())
            .unwrap_or_default()
    }

    fn assert_lofty_id3_multivalue_round_trip(path: &std::path::Path) {
        assert_eq!(
            crate::metadata_persistence::metadata_backend_for_path(path)
                .expect("classify ID3 fixture"),
            crate::metadata_persistence::MetadataPersistenceBackend::LoftyId3v2,
        );

        let artist_values = ["Alice", "Alice", "Bob"];
        let composer_values = ["Carol", "Dave", "Dave"];
        let performer_values = ["Miles Davis", "John Coltrane", "Miles Davis"];
        let arranger_values = ["Gil Evans", "Quincy Jones", "Gil Evans"];

        for (display_key, values) in [
            ("ARTIST", artist_values),
            ("COMPOSER", composer_values),
            ("PERFORMER", performer_values),
            ("ARRANGER", arranger_values),
        ] {
            let result = apply_editor_list_change(path, display_key, &values, &[]);
            assert_id3_multivalue_interop_warning(&result, display_key);
            assert_eq!(editor_slot_values(path, display_key), owned_test_values(&values));
        }

        assert_eq!(
            id3_physical_text_values(path, "TPE1"),
            owned_test_values(&artist_values),
        );
        assert_eq!(
            id3_physical_text_values(path, "TCOM"),
            owned_test_values(&composer_values),
        );
        assert_eq!(
            id3_physical_extended_text_value(path, "PERFORMER"),
            performer_values.join("\0"),
            "PERFORMER must use one lossless NUL-delimited TXXX payload",
        );
        assert_eq!(
            id3_physical_extended_text_value(path, "ARRANGER"),
            arranger_values.join("\0"),
            "ARRANGER must use one lossless NUL-delimited TXXX payload",
        );

        // A whole-tag save triggered by an unrelated scalar edit must preserve
        // every repeated field and its canonical physical representation.
        let result = apply_editor_list_change(path, "TITLE", &["Unrelated edit"], &[]);
        for display_key in ["ARTIST", "COMPOSER", "PERFORMER", "ARRANGER"] {
            assert_id3_multivalue_interop_warning(&result, display_key);
        }
        for (display_key, values) in [
            ("ARTIST", artist_values),
            ("COMPOSER", composer_values),
            ("PERFORMER", performer_values),
            ("ARRANGER", arranger_values),
        ] {
            assert_eq!(editor_slot_values(path, display_key), owned_test_values(&values));
        }
        assert_eq!(id3_physical_text_values(path, "TPE1"), owned_test_values(&artist_values));
        assert_eq!(id3_physical_text_values(path, "TCOM"), owned_test_values(&composer_values));
        assert_eq!(id3_physical_extended_text_value(path, "PERFORMER"), performer_values.join("\0"));
        assert_eq!(id3_physical_extended_text_value(path, "ARRANGER"), arranger_values.join("\0"));

        let before = std::fs::read(path).expect("snapshot ID3 multi-value carrier");
        let result = apply_editor_list_change(path, "ARRANGER", &arranger_values, &[]);
        assert_id3_multivalue_interop_warning(&result, "ARRANGER");
        assert_eq!(
            std::fs::read(path).expect("read repeated ID3 multi-value save"),
            before,
            "repeating an already-satisfied ID3 multi-value edit must be byte-identical",
        );
    }

    fn isolated_metadata_journal_home(
        prefix: &str,
    ) -> crate::tui::test_support::XdgConfigHomeGuard {
        let guard = crate::tui::test_support::XdgConfigHomeGuard::new(prefix);
        assert_eq!(
            crate::db::db_path(),
            guard.path().join("data").join("tonepoet").join("tonepoet.db"),
            "metadata editor test must resolve its journal inside the per-test XDG data home",
        );
        guard
    }

    fn native_ape_physical_text_values(
        path: &std::path::Path,
        display_key: &str,
    ) -> Vec<String> {
        let tag = read_native_ape_tag(path)
            .expect("read native APEv2 tag")
            .expect("carrier has native APEv2 tag");
        let items = tag
            .items
            .iter()
            .filter(|item| {
                item.key
                    .as_deref()
                    .is_some_and(|key| native_ape_canonical_key(key) == display_key)
            })
            .collect::<Vec<_>>();
        assert_eq!(
            items.len(),
            1,
            "{display_key} must persist as exactly one APEv2 multi-value item",
        );
        let item = items[0];
        assert_eq!(
            item.item_type(),
            APE_ITEM_TYPE_TEXT,
            "{display_key} must persist as an APEv2 text item",
        );
        let text = std::str::from_utf8(&item.value).expect("APEv2 text item is UTF-8");
        text.split('\0').map(str::to_string).collect()
    }

    fn assert_vorbis_multivalue_editor_round_trip(
        file_name: &str,
        fixture: &[u8],
        expected_backend: crate::metadata_persistence::MetadataPersistenceBackend,
    ) {
        let _xdg = isolated_metadata_journal_home("tonepoet-vorbis-multivalue-round-trip");
        let (_temp, path) = copy_numbering_fixture(file_name, fixture);
        assert_eq!(
            crate::metadata_persistence::metadata_backend_for_path(&path)
                .expect("classify Vorbis-family carrier"),
            expected_backend,
        );

        let initial = ["Alice", "Alice", "Bob"];
        assert_saved_without_warnings(&apply_editor_list_change(
            &path, "COMPOSER", &initial, &[],
        ));
        assert_eq!(editor_slot_values(&path, "COMPOSER"), owned_test_values(&initial));
        assert_eq!(lofty_vorbis_physical_values(&path, "COMPOSER"), owned_test_values(&initial));

        // Unrelated editor write must leave repeated COMPOSER carriers intact.
        assert_saved_without_warnings(&apply_editor_list_change(
            &path, "TITLE", &["Unrelated edit"], &[],
        ));
        assert_eq!(editor_slot_values(&path, "COMPOSER"), owned_test_values(&initial));
        assert_eq!(lofty_vorbis_physical_values(&path, "COMPOSER"), owned_test_values(&initial));

        // Exercise edit, deletion, reordering, duplicate retention, and append
        // in one persisted target list.
        let edited = ["Bob (edited)", "Alice", "Alice", "Carol"];
        assert_saved_without_warnings(&apply_editor_list_change(
            &path, "COMPOSER", &edited, &initial,
        ));
        assert_eq!(editor_slot_values(&path, "COMPOSER"), owned_test_values(&edited));
        assert_eq!(lofty_vorbis_physical_values(&path, "COMPOSER"), owned_test_values(&edited));

        let bytes = std::fs::read(&path).expect("snapshot accepted repeated-value write");
        assert_saved_without_warnings(&apply_editor_list_change(
            &path, "COMPOSER", &edited, &initial,
        ));
        assert_eq!(
            std::fs::read(&path).expect("read repeated no-op save"),
            bytes,
            "repeating an already-satisfied multi-value edit must be byte-identical",
        );

        let performer = ["Performer A", "Performer B", "Performer A"];
        let arranger = ["Arranger A", "Arranger B", "Arranger A"];
        for (display_key, values) in [("PERFORMER", performer), ("ARRANGER", arranger)] {
            assert_saved_without_warnings(&apply_editor_list_change(
                &path, display_key, &values, &[],
            ));
            assert_eq!(editor_slot_values(&path, display_key), owned_test_values(&values));
            assert_eq!(
                lofty_vorbis_physical_values(&path, display_key),
                owned_test_values(&values),
            );
        }

        assert_saved_without_warnings(&apply_editor_list_change(
            &path,
            "TITLE",
            &["Preserve repeated names"],
            &[],
        ));
        for (display_key, values) in [("PERFORMER", performer), ("ARRANGER", arranger)] {
            assert_eq!(editor_slot_values(&path, display_key), owned_test_values(&values));
            assert_eq!(
                lofty_vorbis_physical_values(&path, display_key),
                owned_test_values(&values),
            );
        }
    }

